# osprey: flavor=python
@effect
class Drafts:
    def save(path: str, text: str) -> Result[int, Error]: ...

def saveDraft():
    match perform(Drafts.save("draft.txt", "Ship it.")):
        case Success():
            return "Saved"
        case Error(message=message):
            return f"Retry: {message}"

@handler(Drafts)
class disk:
    def save(path, text):
        return writeFile(path, text)

@handler(Drafts)
class offline:
    def save(_path, _text):
        return Error(message="offline")

def main():
    print(f"{disk(saveDraft)} / {offline(saveDraft)}")
